ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns orc http://orchestration.cloud.etb.com.co
---
{
  soapenv#"Envelope": {
    soapenv#"Header": null,
    soapenv#"Body": {
      orc#"RunOrchService": {
        orc#"OrchInput": {
          orc#"OrchRequestHeader": {
            orc#"ExternalId": "PORTAL_LTE_",
            orc#"System": "PORTALLTE"
          },
          orc#"OrchRequestBody": {
            orc#"Id": payload.id,
            orc#"Parameters": {
              orc#"Parameter": {
                orc#"Attribute": "ORDER_NUM",
                orc#"Value": payload.orderNumber
              }
            }
          }
        }
      }
    }
  }
}
